def transform(g):
 h,w=len(g),len(g[0]); col=next(v for v in {v for row in g for v in row} if v not in (0,9)); pts=[(r,c) for r in range(h) for c in range(w) if g[r][c]==col]; out=[r[:] for r in g]; forms=set()
 for flip in (1,-1):
  for k in range(4):
   z=[]
   for y,x in pts:
    x*=flip
    for _ in range(k): y,x=x,-y
    z.append((y,x))
   my=min(y for y,x in z); mx=min(x for y,x in z); forms.add(tuple(sorted((y-my,x-mx) for y,x in z)))
 for form in forms:
  mh=max(y for y,x in form)+1; mw=max(x for y,x in form)+1
  for r in range(h-mh+1):
   for c in range(w-mw+1):
    if all(g[r+y][c+x]==0 for y,x in form):
     for y,x in form: out[r+y][c+x]=col
 return out
